/**
 * How a PagerDuty setting turns into a value. An omitted setting reads its
 * well-known env var / deployment secret, which on Cursor hosting is the
 * addressed installation's own secret of that name. An authored
 * `{ secretName }` reads that secret instead and never falls back.
 */
import { resolveWebhookSecretValue, } from "../../internal/named-webhook-secret.js";
import { isSecretRef } from "../../types.js";
/**
 * The secret name a setting reads: the authored `{ secretName }`, the
 * default name when the setting is omitted, or `undefined` for a literal
 * or getter authored in code.
 */
export function pagerDutySecretName(value, defaultName) {
    if (value === undefined) {
        return defaultName;
    }
    return isSecretRef(value) ? value.secretName : undefined;
}
/** The setting's value, read now; blank counts as unset. */
export function resolvePagerDutySecret(value, defaultName) {
    return resolveWebhookSecretValue(value ?? { secretName: defaultName });
}
